    hsnSac: hsnSac.present ? hsnSac.value : this.hsnSac,
    taxRateBasisPoints: taxRateBasisPoints ?? this.taxRateBasisPoints,
    attributesJson: attributesJson ?? this.attributesJson,
    discountType: discountType ?? this.discountType,
