    baseAmountMinor: baseAmountMinor ?? this.baseAmountMinor,
    discountAmountMinor: discountAmountMinor ?? this.discountAmountMinor,
    taxableAmountMinor: taxableAmountMinor ?? this.taxableAmountMinor,
